-- Initial catalog only. Future content edits go through the admin RPC.
 select p.telegram_user_id,a.branch_id,count(*)::double precision / (select count(*) from public.achievement_catalog c where c.branch_id=a.branch_id and c.active)
 from public.user_progress p join public.achievement_catalog a on a.id=p.achievement_id where a.active group by p.telegram_user_id,a.branch_id
 on conflict(telegram_user_id,branch_id) do nothing;
